import json, urllib.request, ssl, base64

min_level = int("$min_alert_level")

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

creds = "$opensearch_user:$opensearch_pass"
auth = base64.b64encode(creds.encode()).decode()
headers = {"Content-Type": "application/json", "Authorization": f"Basic {auth}"}
errors = []

def is_private(ip):
    return ip.startswith("10.") or ip.startswith("192.168.") or ip.startswith("172.16.")

def os_post(path, body):
    req = urllib.request.Request(
        f"$opensearch_url{path}",
        data=json.dumps(body).encode(),
        headers=headers,
        method="POST"
    )
    resp = urllib.request.urlopen(req, context=ctx, timeout=20)
    return json.loads(resp.read().decode())

def run_ip_agg(ip_field):
    """Aggregate alerts by an IP field, return {ip: {count, max_level, top_rule, agents}}."""
    query = {
        "size": 0,
        "track_total_hits": True,
        "query": {
            "bool": {
                "filter": [
                    {"range": {"timestamp": {"gte": "now-24h"}}},
                    {"range": {"rule.level": {"gte": min_level}}},
                    {"exists": {"field": ip_field}}
                ]
            }
        },
        "aggs": {
            "by_ip": {
                "terms": {"field": ip_field, "size": 200},
                "aggs": {
                    "max_level": {"max": {"field": "rule.level"}},
                    "top_rule": {"terms": {"field": "rule.description.keyword", "size": 1}},
                    "agents": {"terms": {"field": "agent.name", "size": 3}}
                }
            }
        }
    }
    r = os_post("/wazuh-alerts-*/_search", query)
    total = r.get("hits", {}).get("total", {}).get("value", 0)
    details = {}
    for b in r.get("aggregations", {}).get("by_ip", {}).get("buckets", []):
        ip = b["key"]
        if is_private(ip):
            continue
        rule_buckets = b.get("top_rule", {}).get("buckets", [])
        agent_buckets = b.get("agents", {}).get("buckets", [])
        details[ip] = {
            "count": b["doc_count"],
            "max_level": int(b.get("max_level", {}).get("value", 0) or 0),
            "top_rule": rule_buckets[0]["key"] if rule_buckets else "",
            "agents": [a["key"] for a in agent_buckets]
        }
    return details, total

wazuh_details = {}
wazuh_total = 0

# Query A: aggregate by data.srcip
try:
    src_details, src_total = run_ip_agg("data.srcip")
    wazuh_details.update(src_details)
    wazuh_total = src_total
except Exception as e:
    errors.append(f"srcip: {str(e)[:150]}")

# Query B: aggregate by data.dstip, merge into same dict
try:
    dst_details, dst_total = run_ip_agg("data.dstip")
    for ip, info in dst_details.items():
        if ip in wazuh_details:
            existing = wazuh_details[ip]
            existing["count"] += info["count"]
            if info["max_level"] > existing["max_level"]:
                existing["max_level"] = info["max_level"]
                existing["top_rule"] = info["top_rule"]
            for a in info["agents"]:
                if a not in existing["agents"]:
                    existing["agents"].append(a)
        else:
            wazuh_details[ip] = info
    wazuh_total = max(wazuh_total, dst_total)
except Exception as e:
    errors.append(f"dstip: {str(e)[:150]}")

wazuh_ips = sorted(wazuh_details.keys())

print(json.dumps({
    "wazuh_ips": wazuh_ips,
    "wazuh_details": wazuh_details,
    "wazuh_total": wazuh_total,
    "min_level_used": min_level,
    "errors": errors
}))

import json, urllib.request, ssl, base64

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

creds = "$elk_user:$elk_pass"
auth = base64.b64encode(creds.encode()).decode()
headers = {"Content-Type": "application/json", "Authorization": f"Basic {auth}"}
errors = []

def is_private(ip):
    return ip.startswith("10.") or ip.startswith("192.168.") or ip.startswith("172.16.")

def es_post(path, body):
    req = urllib.request.Request(
        f"$elk_url{path}",
        data=json.dumps(body).encode(),
        headers=headers,
        method="POST"
    )
    resp = urllib.request.urlopen(req, context=ctx, timeout=20)
    return json.loads(resp.read().decode())

def run_tier1_agg(ip_field):
    """Aggregate tier1 events by an IP field."""
    query = {
        "size": 0,
        "track_total_hits": True,
        "query": {
            "bool": {
                "filter": [
                    {"term": {"tags": "tier1_ti_match"}},
                    {"range": {"@timestamp": {"gte": "now-24h"}}}
                ]
            }
        },
        "aggs": {
            "by_ip": {
                "terms": {"field": ip_field, "size": 200},
                "aggs": {
                    "providers": {"terms": {"field": "ti.provider", "size": 3}},
                    "types": {"terms": {"field": "ti.type", "size": 3}}
                }
            }
        }
    }
    r = es_post("/logs-zeek.haccp-default/_search", query)
    total = r.get("hits", {}).get("total", {}).get("value", 0)
    details = {}
    for b in r.get("aggregations", {}).get("by_ip", {}).get("buckets", []):
        ip = b["key"]
        if is_private(ip):
            continue
        prov_buckets = b.get("providers", {}).get("buckets", [])
        type_buckets = b.get("types", {}).get("buckets", [])
        details[ip] = {
            "count": b["doc_count"],
            "ti_providers": [p["key"] for p in prov_buckets],
            "ti_types": [t["key"] for t in type_buckets]
        }
    return details, total

tier1_details = {}
tier1_total = 0

# Query A: aggregate by id_resp_h (destination IPs matching TI)
try:
    resp_details, resp_total = run_tier1_agg("id_resp_h")
    tier1_details.update(resp_details)
    tier1_total = resp_total
except Exception as e:
    errors.append(f"id_resp_h: {str(e)[:150]}")

# Query B: aggregate by id_orig_h (source IPs generating tier1 traffic)
try:
    orig_details, orig_total = run_tier1_agg("id_orig_h")
    for ip, info in orig_details.items():
        if ip in tier1_details:
            existing = tier1_details[ip]
            existing["count"] += info["count"]
            for p in info["ti_providers"]:
                if p not in existing["ti_providers"]:
                    existing["ti_providers"].append(p)
            for t in info["ti_types"]:
                if t not in existing["ti_types"]:
                    existing["ti_types"].append(t)
        else:
            tier1_details[ip] = info
except Exception as e:
    errors.append(f"id_orig_h: {str(e)[:150]}")

tier1_ips = sorted(tier1_details.keys())

print(json.dumps({
    "tier1_ips": tier1_ips,
    "tier1_details": tier1_details,
    "tier1_total": tier1_total,
    "errors": errors
}))
